python3 - <<'E'
p='src/main.rs'
s=open(p).read()
s=s.replace("    done: bool,\n}","    done: bool,\n    prio: u8,\n}",1)
s=s.replace("done: false });","done: false, prio: 5 });",1)
old=s[s.index('        } else if command == "list" {'):s.index("    }\n}\n")]
new='''        } else if command == "prio" {
            let mut args = rest.split_whitespace();
            let id_text = args.next().unwrap_or("");
            let p_text = args.next().unwrap_or("");
            let id = id_text.parse::<i64>().ok();
            match id.and_then(|id| find(&mut tasks, id)) {
                None => println!("no such task {}", id_text),
                Some(task) => match p_text.as_bytes() {
                    [digit @ b'0'..=b'9'] => {
                        task.prio = digit - b'0';
                        println!("prio {} {}", task.id, task.prio);
                    }
                    _ => println!("bad priority {}", p_text),
                },
            }
        } else if command == "list" {
            let all = rest == "all";
            let mut shown: Vec<&Task> =
                tasks.iter().filter(|task| all || !task.done).collect();
            shown.sort_by_key(|task| (task.prio, task.id));
            for task in shown {
                if all {
                    let mark = if task.done { 'x' } else { '-' };
                    println!("{} {} {}", mark, task.id, task.title);
                } else {
                    println!("{} {}", task.id, task.title);
                }
            }
        } else if let Some(word) = line.split_whitespace().next() {
            println!("? {}", word);
        }
'''
s=s.replace(old,new)
open(p,'w').write(s)
E
